ee:message.ee:set-payload:
%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:BAD_REQUEST",
								errDescription: "Bad Request",
								errMessage: error.description default "Bad Request"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:NOT_FOUND",
								errDescription: "Resource not found",
								errMessage: error.description default "Resource not found"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:METHOD_NOT_ALLOWED",
								errDescription: "Method not allowed",
								errMessage: error.description default "Method not allowed"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:NOT_ACCEPTABLE",
								errDescription: "Not acceptable",
								errMessage: error.description default "Not acceptable"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:UNSUPPORTED_MEDIA_TYPE",
								errDescription: "Unsupported media type",
								errMessage: error.description default "Unsupported media type"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APIKIT:NOT_IMPLEMENTED",
								errDescription: "Not Implemented",
								errMessage: error.description default "Not Implemented"
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "HTTP:BAD_REQUEST",
								errDescription: "Invalid Request",
								errMessage: 'Duplicate Object'
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: 'APP:TECHNICAL_ERROR',
								errDescription: p('error.message.generic'),
								errMessage: p('error.message.generic')
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "HTTP:BAD_REQUEST",
								errDescription: error.description,
								errMessage: error.description
							}
						}

%dw 2.0
						output application/json
						---
						{
							errorDetails: {
								errType: "APP:ORG_NOT_MAPPED",
								errDescription: error.description,
								errMessage: error.description
							}
						}
